mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM iam.delegations
    WHERE is_deleted = FALSE
      AND delegator_id = #{delegatorId}
      AND status = 'ACTIVE'
      AND end_at > NOW()
      AND start_at < #{endAt}
      AND end_at > #{startAt}
)

mapper.update:
UPDATE iam.delegations
SET status = #{status},
    updated_by = #{actorId}
WHERE id = #{delegationId}
  AND is_deleted = FALSE
